const updateCertificate = `-- name: UpdateCertificate :execrows
UPDATE certificates
SET component_id = $1,
    certificate_name = $2,
    issue_date = $3,
    expiry_date = $4,
    certificate_file = $5,
    issuing_authority = $6,
    status = $7,
    test_id = $8,
    imca_ref = $9,
    imca_d018 = $10,
    maintenance_notes = $11,
    updated_at = NOW()
WHERE certificate_id = $12
`

type UpdateCertificateParams struct {
	ComponentID      uuid.UUID  `json:"component_id"`
	CertificateName  string     `json:"certificate_name"`
	IssueDate        *time.Time `json:"issue_date"`
	ExpiryDate       *time.Time `json:"expiry_date"`
	CertificateFile  string     `json:"certificate_file"`
	IssuingAuthority string     `json:"issuing_authority"`
	Status           string     `json:"status"`
	TestID           uuid.UUID  `json:"test_id"`
	ImcaRef          string     `json:"imca_ref"`
	ImcaD018         string     `json:"imca_d018"`
	MaintenanceNotes string     `json:"maintenance_notes"`
	CertificateID    uuid.UUID  `json:"certificate_id"`
}

func (q *Queries) UpdateCertificate(ctx context.Context, arg UpdateCertificateParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateCertificate,
		arg.ComponentID,
		arg.CertificateName,
		arg.IssueDate,
		arg.ExpiryDate,
		arg.CertificateFile,
		arg.IssuingAuthority,
		arg.Status,
		arg.TestID,
		arg.ImcaRef,
		arg.ImcaD018,
		arg.MaintenanceNotes,
		arg.CertificateID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

